/**
 * Schedule resolution for reminders (`every` / `cron` / `delay` / `at`).
 */
import { parseCron } from "./cron.js";
import { parseDuration } from "./duration.js";
/** @deprecated Deprecated on the package root. */
export class ReminderValidationError extends Error {
    constructor(message) {
        super(message);
        this.name = "ReminderValidationError";
    }
}
/** Node setTimeout overflows past ~2^31-1 ms (~24.8d); chunk long waits. */
export const MAX_TIMER_MS = 2_147_483_647;
/**
 * Resolve create-input schedule fields into a concrete next-fire plan.
 * Pass `nowMs` for deterministic CP / test resolution; CP owns this call.
 */
export function resolveSchedule(input, nowMs = Date.now()) {
    const shapes = [
        input.every !== undefined,
        input.cron !== undefined,
        input.delay !== undefined,
        input.at !== undefined,
    ].filter(Boolean);
    if (shapes.length !== 1) {
        throw new ReminderValidationError("reminders.create requires exactly one of every, cron, delay, or at");
    }
    if (input.every !== undefined) {
        const intervalMs = parseDuration(input.every);
        if (intervalMs <= 0) {
            throw new ReminderValidationError(`every must be > 0 (got ${input.every})`);
        }
        return {
            kind: "every",
            value: input.every,
            intervalMs,
            nextFireAtMs: nowMs + intervalMs,
        };
    }
    if (input.cron !== undefined) {
        parseCron(input.cron); // validate
        return {
            kind: "cron",
            value: input.cron,
            nextFireAtMs: nextCronFireMs(input.cron, nowMs),
        };
    }
    if (input.delay !== undefined) {
        const delayMs = parseDuration(input.delay);
        return {
            kind: "delay",
            value: String(input.delay),
            nextFireAtMs: nowMs + delayMs,
        };
    }
    const atMs = typeof input.at === "number"
        ? input.at
        : input.at instanceof Date
            ? input.at.getTime()
            : Date.parse(String(input.at));
    if (!Number.isFinite(atMs)) {
        throw new ReminderValidationError(`Invalid at time: ${String(input.at)}`);
    }
    return {
        kind: "at",
        value: typeof input.at === "string" ? input.at : new Date(atMs).toISOString(),
        nextFireAtMs: atMs,
    };
}
/** Next UTC fire strictly after `afterMs` for a 5-field cron. */
export function nextCronFireMs(cronSource, afterMs) {
    try {
        return parseCron(cronSource).nextFire(new Date(afterMs)).getTime();
    }
    catch (error) {
        throw new ReminderValidationError(error instanceof Error ? error.message : `Could not find next fire for cron "${cronSource}"`);
    }
}
/** Default busy policy: recurring may skip; one-shots queue behind the turn. */
export function defaultBusyPolicy(kind) {
    return kind === "every" || kind === "cron" ? "skipIfBusy" : "queueBehindTurn";
}
